const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const r = parseInt(line.trim(), 10);
    let found = false;

    // Upper bound for x derived from x^2 + 3x + 1 <= r => x^2 < r => x < sqrt(r)
    // Loop up to floor(sqrt(r)) + 1 to be safe against boundaries.
    const limit = Math.floor(Math.sqrt(r)) + 1;

    for (let x = 1; x <= limit; x++) {
        // H(x, y) = x^2 + 2xy + x + 1 = r
        // 2xy = r - x^2 - x - 1
        const num = r - x * x - x - 1;

        if (num <= 0) {
            // Since num decreases as x increases, we can stop early.
            break;
        }

        const den = 2 * x;

        if (num % den === 0) {
            const y = num / den;
            if (y >= 1) {
                console.log(`${x} ${y}`);
                found = true;
                break;
            }
        }
    }

    if (!found) {
        console.log("NO");
    }

    rl.close();
});
